from pypdf import PdfReader
r=PdfReader('manuscript.pdf')
uris=set()
for page in r.pages:
    for ref in page.get('/Annots', []):
        a=ref.get_object().get('/A')
        if a and a.get('/URI'):
            uris.add(str(a['/URI']))
print('External PDF links:', sorted(uris))
# Apply the published expansion predicates to a minimal shared-stimulus graph.
E={('A','x'),('A','y'),('B','x'),('B','y')}
train={('A','x')}; test={('B','y')}
eeg_train=train|{(u,v) for u,v in E if u"'!='"'B'}
eeg_test=test|{(u,v) for u,v in E if u"'!='"'A'}
fmri_train=train|{(u,v) for u,v in E if v"'!='"'y'}
fmri_test=test|{(u,v) for u,v in E if v"'!='"'x'}
print('Algorithm 1 train:', sorted(eeg_train), 'test:', sorted(eeg_test))
print('Algorithm 1 overlapping stimuli:', sorted({v for u,v in eeg_train}&{v for u,v in eeg_test}))
print('Algorithm 2 train:', sorted(fmri_train), 'test:', sorted(fmri_test))
print('Algorithm 2 overlapping subjects:', sorted({u for u,v in fmri_train}&{u for u,v in fmri_test}))
PY"
